SELECT CASE WHEN discount_pct >= 0.3 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, promo_code, COUNT(DISTINCT promo_code) AS distinct_promo_codes, COUNT(DISTINCT id) AS distinct_ids, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN channel = 'store' THEN 1 END), 0), 2) AS discount_pct_per_store, STDDEV_SAMP(discount_pct) AS discount_pct_stddev FROM promotions GROUP BY CASE WHEN discount_pct >= 0.3 THEN 'PREMIUM' ELSE 'STANDARD' END, promo_code HAVING distinct_ids >= 1 ORDER BY distinct_promo_codes DESC NULLS FIRST;
